// src/app/page.tsx
'use client';

import { useState, useEffect } from 'react';

export default function Home() {
  const [authStatus, setAuthStatus] = useState<string | null>(null);
  const [meetings, setMeetings] = useState<any[]>([]);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const auth = params.get('auth');

    if (auth === 'success') {
      setAuthStatus('Authentication successful!');
      fetchGoogleMeetings();
    } else if (auth === 'failure') {
      setAuthStatus('Authentication failed. Please try again.');
    }
  }, []);

  const fetchGoogleMeetings = async () => {
    try {
      const response = await fetch('/api/google-meetings');
      const data = await response.json();
      setMeetings(data.meetings || []);
    } catch (error) {
      console.error('Error fetching meetings:', error);
      setAuthStatus('Failed to fetch Google Meet data.');
    }
  };

  const handleAuth = () => {
    window.location.href = '/api/auth';
  };

  return (
    <main style={{ padding: '2rem', textAlign: 'center' }}>
      <h1>Google Meet Integration</h1>
      <p>Authenticate and interact with Google Meet.</p>
      <button
        onClick={handleAuth}
        style={{
          padding: '10px 20px',
          backgroundColor: '#4285F4',
          color: 'white',
          border: 'none',
          borderRadius: '5px',
          cursor: 'pointer',
          marginBottom: '1rem',
        }}
      >
        Authenticate with Google
      </button>
      {authStatus && <p>{authStatus}</p>}
      {meetings.length > 0 && (
        <div>
          <h2>Google Meet Sessions</h2>
          <ul>
            {meetings.map((meeting) => (
              <li key={meeting.id}>
                <strong>{meeting.title}</strong> - {meeting.startTime}
              </li>
            ))}
          </ul>
        </div>
      )}
    </main>
  );
}
